export function OrganisationTree({
  rootName = "{{rootName}}",
  expanded = {{expanded}},
  color = "{{color}}",
  density = "{{density}}",
}) {
  const pad = density === "compact" ? "2px 6px" : "4px 8px";
  const label = { cursor: "pointer", padding: pad, borderLeft: `3px solid ${color}`, fontWeight: 600 };
  const children = { margin: 0, paddingLeft: 22, listStyle: "none", borderLeft: "1px dashed #24143033" };
  return (
    <details open={expanded} style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430" }}>
      <summary style={label}>{rootName}</summary>
      <ul style={children}>
        <li>
          <details>
            <summary style={label}>Engineering</summary>
            <ul style={children}>
              <li><span style={{ display: "inline-block", padding: pad }}>Platform</span></li>
              <li><span style={{ display: "inline-block", padding: pad }}>Product</span></li>
            </ul>
          </details>
        </li>
        <li><span style={{ display: "inline-block", padding: pad }}>Design</span></li>
      </ul>
    </details>
  );
}
